from pathlib import Path

ROUTES = Path("artifacts/api-server/src/routes/execution.ts")
ENGINE = Path("artifacts/api-server/src/lib/execution-engine.ts")
WORKER = Path("artifacts/api-server/src/lib/strategy-worker.ts")

def replace_once(text, old, new, label):
    if old not in text:
        raise SystemExit(f"Could not patch {label}: expected block not found")
    return text.replace(old, new, 1)

routes = ROUTES.read_text()
routes = replace_once(routes, '  walletSolBalance,\n  withdrawSol,\n  walletDeletionState,\n} from "../lib/execution-engine";\n', '  walletSolBalance,\n  walletTokenBalance,\n  withdrawSol,\n  walletDeletionState,\n} from "../lib/execution-engine";\n', 'execution engine import')
routes = replace_once(routes, 'async function findWallet(address: string) {\n  const rows = await db\n    .select()\n    .from(executionWalletsTable)\n    .where(eq(executionWalletsTable.address, address))\n    .limit(1);\n\n  return rows[0] ?? null;\n}\n', 'async function findWallet(address: string) {\n  const rows = await db\n    .select()\n    .from(executionWalletsTable)\n    .where(eq(executionWalletsTable.address, address))\n    .limit(1);\n\n  return rows[0] ?? null;\n}\n\nasync function findStrategy(walletId: string, mint: string) {\n  const rows = await db\n    .select()\n    .from(executionStrategiesTable)\n    .where(\n      and(\n        eq(executionStrategiesTable.walletId, walletId),\n        eq(executionStrategiesTable.mint, mint),\n      ),\n    )\n    .limit(1);\n\n  return rows[0] ?? null;\n}\n\nasync function lockStrategyForManualTrade(\n  walletId: string,\n  mint: string,\n) {\n  const strategy = await findStrategy(walletId, mint);\n\n  if (!strategy?.enabled) {\n    return strategy;\n  }\n\n  if (strategy.state === "executing") {\n    throw new Error(\n      "AUTO is executing for this wallet. Retry the manual trade in a moment.",\n    );\n  }\n\n  await db\n    .update(executionStrategiesTable)\n    .set({\n      state: "executing",\n      updatedAt: new Date(),\n      lastError: null,\n    })\n    .where(eq(executionStrategiesTable.id, strategy.id));\n\n  return strategy;\n}\n\nasync function restoreStrategyAfterManualFailure(\n  strategy: Awaited<ReturnType<typeof findStrategy>>,\n  error: unknown,\n) {\n  if (!strategy?.enabled) return;\n\n  await db\n    .update(executionStrategiesTable)\n    .set({\n      state: "watching",\n      lastError:\n        error instanceof Error\n          ? error.message\n          : String(error),\n      updatedAt: new Date(),\n    })\n    .where(eq(executionStrategiesTable.id, strategy.id));\n}\n\nasync function finishManualSell(\n  strategy: Awaited<ReturnType<typeof findStrategy>>,\n  percentage: number,\n  signature: string,\n) {\n  if (!strategy) return;\n\n  const fullExit = percentage >= 100;\n\n  await db\n    .update(executionStrategiesTable)\n    .set({\n      enabled: fullExit ? false : strategy.enabled,\n      entryPriceSol: fullExit\n        ? null\n        : strategy.entryPriceSol,\n      tpFired: fullExit\n        ? false\n        : strategy.tpFired,\n      state: fullExit\n        ? "closed"\n        : strategy.enabled\n          ? "watching"\n          : "idle",\n      lastTrigger: "manual-sell",\n      lastSignature: signature,\n      lastError: null,\n      updatedAt: new Date(),\n    })\n    .where(eq(executionStrategiesTable.id, strategy.id));\n}\n\nasync function tokenBalanceAfterBuy(\n  address: string,\n  mint: string,\n  beforeBalance: number,\n): Promise<number> {\n  let latest = beforeBalance;\n\n  for (let attempt = 0; attempt < 4; attempt += 1) {\n    latest = await walletTokenBalance(address, mint);\n    if (latest > beforeBalance) return latest;\n\n    if (attempt < 3) {\n      await new Promise((resolve) => setTimeout(resolve, 300));\n    }\n  }\n\n  return latest;\n}\n\nasync function updateWeightedEntryAfterBuy(\n  walletId: string,\n  address: string,\n  mint: string,\n  amountSol: number,\n  beforeBalance: number,\n  previousStrategy: Awaited<ReturnType<typeof findStrategy>>,\n) {\n  const afterBalance = await tokenBalanceAfterBuy(\n    address,\n    mint,\n    beforeBalance,\n  );\n\n  const acquired = Math.max(0, afterBalance - beforeBalance);\n\n  let entryPriceSol: number;\n\n  if (acquired > 0) {\n    if (\n      beforeBalance > 0 &&\n      previousStrategy?.entryPriceSol &&\n      previousStrategy.entryPriceSol > 0\n    ) {\n      const priorCost =\n        beforeBalance * previousStrategy.entryPriceSol;\n\n      entryPriceSol =\n        (priorCost + amountSol) / afterBalance;\n    } else if (beforeBalance <= 0) {\n      entryPriceSol = amountSol / acquired;\n    } else {\n      const current = await currentPriceSol(mint);\n      const estimatedPriorCost = beforeBalance * current;\n      entryPriceSol =\n        (estimatedPriorCost + amountSol) / afterBalance;\n    }\n  } else {\n    entryPriceSol = await currentPriceSol(mint);\n  }\n\n  if (!Number.isFinite(entryPriceSol) || entryPriceSol <= 0) {\n    throw new Error("Could not calculate the weighted entry price");\n  }\n\n  const enabled = previousStrategy?.enabled ?? false;\n\n  await db\n    .insert(executionStrategiesTable)\n    .values({\n      walletId,\n      mint,\n      enabled,\n      entryPriceSol,\n      tpFired: false,\n      state: enabled ? "watching" : "idle",\n      updatedAt: new Date(),\n    })\n    .onConflictDoUpdate({\n      target: [\n        executionStrategiesTable.walletId,\n        executionStrategiesTable.mint,\n      ],\n      set: {\n        entryPriceSol,\n        tpFired: false,\n        state: enabled ? "watching" : "idle",\n        lastTrigger: null,\n        lastSignature: null,\n        lastError: null,\n        updatedAt: new Date(),\n      },\n    });\n}\n', 'manual/auto coordination helpers')
routes = replace_once(routes, 'async function setEntryPrice(walletId: string, mint: string) {\n  const price = await currentPriceSol(mint);\n\n  await db\n    .insert(executionStrategiesTable)\n    .values({\n      walletId,\n      mint,\n      enabled: false,\n      entryPriceSol: price,\n      tpFired: false,\n      state: "idle",\n      updatedAt: new Date(),\n    })\n    .onConflictDoUpdate({\n      target: [\n        executionStrategiesTable.walletId,\n        executionStrategiesTable.mint,\n      ],\n      set: {\n        entryPriceSol: price,\n        tpFired: false,\n        state: "idle",\n        lastTrigger: null,\n        lastSignature: null,\n        lastError: null,\n        updatedAt: new Date(),\n      },\n    });\n}\n\n', '', 'remove last-buy entry price helper')
routes = replace_once(routes, 'router.post("/execution/trade", async (req, res): Promise<void> => {\n  const {\n    address,\n    mint,\n    side,\n    amountSol,\n    sellPct,\n  } = req.body ?? {};\n\n  if (\n    typeof address !== "string" ||\n    typeof mint !== "string" ||\n    (side !== "buy" && side !== "sell")\n  ) {\n    res.status(400).json({ error: "Invalid trade request" });\n    return;\n  }\n\n  const wallet = await findWallet(address);\n  if (!wallet || !wallet.enabled) {\n    res.status(404).json({ error: "Execution wallet not found" });\n    return;\n  }\n\n  try {\n    const keypair = Keypair.fromSecretKey(\n      decryptSecret(wallet.encryptedSecret),\n    );\n\n    let signature: string;\n\n    if (side === "buy") {\n      const amount = Number(amountSol);\n      if (!Number.isFinite(amount) || amount <= 0) {\n        res.status(400).json({ error: "Invalid SOL amount" });\n        return;\n      }\n\n      signature = await executeBuy(keypair, mint, amount);\n      await setEntryPrice(wallet.id, mint);\n    } else {\n      const percentage = Number(sellPct);\n      signature = await executeSellPercent(\n        keypair,\n        mint,\n        percentage,\n      );\n    }\n\n    res.json({\n      status: "success",\n      side,\n      address,\n      mint,\n      signature,\n    });\n  } catch (error) {\n    req.log.error({ err: error }, "Managed trade failed");\n    res.status(422).json({\n      error:\n        error instanceof Error\n          ? error.message\n          : "Trade failed",\n    });\n  }\n});\n', 'router.post("/execution/trade", async (req, res): Promise<void> => {\n  const {\n    address,\n    mint,\n    side,\n    amountSol,\n    sellPct,\n  } = req.body ?? {};\n\n  if (\n    typeof address !== "string" ||\n    typeof mint !== "string" ||\n    (side !== "buy" && side !== "sell")\n  ) {\n    res.status(400).json({ error: "Invalid trade request" });\n    return;\n  }\n\n  const wallet = await findWallet(address);\n  if (!wallet || !wallet.enabled) {\n    res.status(404).json({ error: "Execution wallet not found" });\n    return;\n  }\n\n  let strategy:\n    Awaited<ReturnType<typeof findStrategy>> = null;\n\n  try {\n    strategy = await lockStrategyForManualTrade(\n      wallet.id,\n      mint,\n    );\n\n    const keypair = Keypair.fromSecretKey(\n      decryptSecret(wallet.encryptedSecret),\n    );\n\n    let signature: string;\n\n    if (side === "buy") {\n      const amount = Number(amountSol);\n      if (!Number.isFinite(amount) || amount <= 0) {\n        res.status(400).json({ error: "Invalid SOL amount" });\n        return;\n      }\n\n      const beforeBalance = await walletTokenBalance(\n        address,\n        mint,\n      );\n\n      signature = await executeBuy(keypair, mint, amount);\n\n      try {\n        await updateWeightedEntryAfterBuy(\n          wallet.id,\n          address,\n          mint,\n          amount,\n          beforeBalance,\n          strategy,\n        );\n      } catch (trackingError) {\n        req.log.error(\n          { err: trackingError, address, mint, signature },\n          "Trade succeeded but weighted entry tracking failed",\n        );\n\n        if (strategy?.enabled) {\n          await db\n            .update(executionStrategiesTable)\n            .set({\n              state: "watching",\n              lastError:\n                trackingError instanceof Error\n                  ? trackingError.message\n                  : String(trackingError),\n              updatedAt: new Date(),\n            })\n            .where(\n              eq(\n                executionStrategiesTable.id,\n                strategy.id,\n              ),\n            );\n        }\n      }\n    } else {\n      const percentage = Number(sellPct);\n\n      if (\n        !Number.isFinite(percentage) ||\n        percentage <= 0 ||\n        percentage > 100\n      ) {\n        res.status(400).json({\n          error: "Sell percentage must be between 0 and 100",\n        });\n        return;\n      }\n\n      signature = await executeSellPercent(\n        keypair,\n        mint,\n        percentage,\n      );\n\n      await finishManualSell(\n        strategy,\n        percentage,\n        signature,\n      );\n    }\n\n    res.json({\n      status: "success",\n      side,\n      address,\n      mint,\n      signature,\n    });\n  } catch (error) {\n    await restoreStrategyAfterManualFailure(\n      strategy,\n      error,\n    );\n\n    req.log.error({ err: error }, "Managed trade failed");\n    res.status(422).json({\n      error:\n        error instanceof Error\n          ? error.message\n          : "Trade failed",\n    });\n  }\n});\n', 'individual trade coordination')
routes = replace_once(routes, 'router.post("/execution/trade-all", async (req, res): Promise<void> => {\n  const { mint, side, amountSol, sellPct } = req.body ?? {};\n\n  if (\n    typeof mint !== "string" ||\n    (side !== "buy" && side !== "sell")\n  ) {\n    res.status(400).json({ error: "Invalid trade-all request" });\n    return;\n  }\n\n  const wallets = await db\n    .select()\n    .from(executionWalletsTable)\n    .where(eq(executionWalletsTable.enabled, true));\n\n  const results: Array<Record<string, unknown>> = [];\n\n  for (const wallet of wallets) {\n    try {\n      const keypair = Keypair.fromSecretKey(\n        decryptSecret(wallet.encryptedSecret),\n      );\n\n      const signature =\n        side === "buy"\n          ? await executeBuy(\n              keypair,\n              mint,\n              Number(amountSol),\n            )\n          : await executeSellPercent(\n              keypair,\n              mint,\n              Number(sellPct),\n            );\n\n      if (side === "buy") {\n        await setEntryPrice(wallet.id, mint);\n      }\n\n      results.push({\n        address: wallet.address,\n        ok: true,\n        signature,\n      });\n    } catch (error) {\n      results.push({\n        address: wallet.address,\n        ok: false,\n        error:\n          error instanceof Error\n            ? error.message\n            : String(error),\n      });\n    }\n  }\n\n  res.json({ results });\n});\n', 'router.post("/execution/trade-all", async (req, res): Promise<void> => {\n  const { mint, side, amountSol, sellPct } = req.body ?? {};\n\n  if (\n    typeof mint !== "string" ||\n    (side !== "buy" && side !== "sell")\n  ) {\n    res.status(400).json({ error: "Invalid trade-all request" });\n    return;\n  }\n\n  const buyAmount = Number(amountSol);\n  const sellPercentage = Number(sellPct);\n\n  if (\n    side === "buy" &&\n    (!Number.isFinite(buyAmount) || buyAmount <= 0)\n  ) {\n    res.status(400).json({ error: "Invalid SOL amount" });\n    return;\n  }\n\n  if (\n    side === "sell" &&\n    (\n      !Number.isFinite(sellPercentage) ||\n      sellPercentage <= 0 ||\n      sellPercentage > 100\n    )\n  ) {\n    res.status(400).json({\n      error: "Sell percentage must be between 0 and 100",\n    });\n    return;\n  }\n\n  const wallets = await db\n    .select()\n    .from(executionWalletsTable)\n    .where(eq(executionWalletsTable.enabled, true));\n\n  const results: Array<Record<string, unknown>> = [];\n\n  for (const wallet of wallets) {\n    let strategy:\n      Awaited<ReturnType<typeof findStrategy>> = null;\n\n    try {\n      strategy = await lockStrategyForManualTrade(\n        wallet.id,\n        mint,\n      );\n\n      const keypair = Keypair.fromSecretKey(\n        decryptSecret(wallet.encryptedSecret),\n      );\n\n      let signature: string;\n\n      if (side === "buy") {\n        const beforeBalance = await walletTokenBalance(\n          wallet.address,\n          mint,\n        );\n\n        signature = await executeBuy(\n          keypair,\n          mint,\n          buyAmount,\n        );\n\n        try {\n          await updateWeightedEntryAfterBuy(\n            wallet.id,\n            wallet.address,\n            mint,\n            buyAmount,\n            beforeBalance,\n            strategy,\n          );\n        } catch (trackingError) {\n          req.log.error(\n            {\n              err: trackingError,\n              address: wallet.address,\n              mint,\n              signature,\n            },\n            "BUY ALL trade succeeded but weighted entry tracking failed",\n          );\n\n          if (strategy?.enabled) {\n            await db\n              .update(executionStrategiesTable)\n              .set({\n                state: "watching",\n                lastError:\n                  trackingError instanceof Error\n                    ? trackingError.message\n                    : String(trackingError),\n                updatedAt: new Date(),\n              })\n              .where(\n                eq(\n                  executionStrategiesTable.id,\n                  strategy.id,\n                ),\n              );\n          }\n        }\n      } else {\n        signature = await executeSellPercent(\n          keypair,\n          mint,\n          sellPercentage,\n        );\n\n        await finishManualSell(\n          strategy,\n          sellPercentage,\n          signature,\n        );\n      }\n\n      results.push({\n        address: wallet.address,\n        ok: true,\n        signature,\n      });\n    } catch (error) {\n      await restoreStrategyAfterManualFailure(\n        strategy,\n        error,\n      );\n\n      results.push({\n        address: wallet.address,\n        ok: false,\n        error:\n          error instanceof Error\n            ? error.message\n            : String(error),\n      });\n    }\n  }\n\n  res.json({ results });\n});\n', 'trade-all coordination')
ROUTES.write_text(routes)

engine = ENGINE.read_text()
engine = replace_once(engine, 'export async function walletSolBalance(address: string): Promise<number> {\n  const lamports = await executionConnection.getBalance(\n    new PublicKey(address),\n    "confirmed",\n  );\n  return lamports / LAMPORTS_PER_SOL;\n}\n', 'export async function walletSolBalance(address: string): Promise<number> {\n  const lamports = await executionConnection.getBalance(\n    new PublicKey(address),\n    "confirmed",\n  );\n  return lamports / LAMPORTS_PER_SOL;\n}\n\nexport async function walletTokenBalance(\n  address: string,\n  mint: string,\n): Promise<number> {\n  const result =\n    await executionConnection.getParsedTokenAccountsByOwner(\n      new PublicKey(address),\n      { mint: new PublicKey(mint) },\n      "confirmed",\n    );\n\n  let total = 0;\n\n  for (const item of result.value) {\n    const data = asRecord(item.account.data);\n    const parsed = asRecord(data.parsed);\n    const info = asRecord(parsed.info);\n    const tokenAmount = asRecord(info.tokenAmount);\n\n    const uiAmountString = stringValue(\n      tokenAmount.uiAmountString,\n    );\n\n    if (uiAmountString != null) {\n      const value = Number(uiAmountString);\n      if (Number.isFinite(value)) {\n        total += value;\n        continue;\n      }\n    }\n\n    const rawAmount = stringValue(tokenAmount.amount);\n    const decimals = numberValue(tokenAmount.decimals);\n\n    if (\n      rawAmount &&\n      /^\\d+$/.test(rawAmount) &&\n      decimals != null\n    ) {\n      const value =\n        Number(rawAmount) / 10 ** decimals;\n\n      if (Number.isFinite(value)) {\n        total += value;\n      }\n    }\n  }\n\n  return total;\n}\n', 'wallet token balance export')
ENGINE.write_text(engine)

worker = WORKER.read_text()
worker = replace_once(worker, '        if (!trigger) continue;\n\n        await db\n          .update(executionStrategiesTable)\n          .set({\n            state: "executing",\n            lastTrigger: trigger,\n            updatedAt: new Date(),\n          })\n          .where(eq(executionStrategiesTable.id, strategy.id));\n', '        if (!trigger) continue;\n\n        const latestRows = await db\n          .select()\n          .from(executionStrategiesTable)\n          .where(eq(executionStrategiesTable.id, strategy.id))\n          .limit(1);\n\n        const latest = latestRows[0];\n\n        if (\n          !latest?.enabled ||\n          latest.state === "executing"\n        ) {\n          continue;\n        }\n\n        await db\n          .update(executionStrategiesTable)\n          .set({\n            state: "executing",\n            lastTrigger: trigger,\n            updatedAt: new Date(),\n          })\n          .where(eq(executionStrategiesTable.id, strategy.id));\n', 'worker re-check before AUTO execution')
WORKER.write_text(worker)

print("v7.0 AUTO/manual coordination patch applied.")
